/// <summary>
/// getFreezeStatus' answer. Message is the text a refused movement shows.
/// </summary>
[DataContractAttribute]
class HSMobileOpsFreezeStatusResponse
{
    boolean success;
    str errorCode;
    boolean frozen;
    str journalId;
    str status;
    str message;
    utcdatetime frozenSinceUtc;
}

Method.Source:
[DataMemberAttribute('Success')]
public boolean parmSuccess(boolean _value = success)
{
    success = _value;
    return success;
}

[DataMemberAttribute('ErrorCode')]
public str parmErrorCode(str _value = errorCode)
{
    errorCode = _value;
    return errorCode;
}

[DataMemberAttribute('Frozen')]
public boolean parmFrozen(boolean _value = frozen)
{
    frozen = _value;
    return frozen;
}

[DataMemberAttribute('JournalId')]
public str parmJournalId(str _value = journalId)
{
    journalId = _value;
    return journalId;
}

[DataMemberAttribute('Status')]
public str parmStatus(str _value = status)
{
    status = _value;
    return status;
}

[DataMemberAttribute('Message')]
public str parmMessage(str _value = message)
{
    message = _value;
    return message;
}

[DataMemberAttribute('FrozenSinceUtc')]
public utcdatetime parmFrozenSinceUtc(utcdatetime _value = frozenSinceUtc)
{
    frozenSinceUtc = _value;
    return frozenSinceUtc;
}
